<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track Order</title><style>body{background:#080e19;color:#fff;font:16px Arial}.box{max-width:500px;margin:8vh auto;padding:22px;background:#192438;border:1px solid #d79a32;border-radius:20px}input,button{box-sizing:border-box;width:100%;padding:14px;margin:8px 0;border-radius:10px}input{background:#0b1220;color:white;border:1px solid #445}button{background:linear-gradient(90deg,#ffb000,#ff432e);border:0;font-weight:bold}.result{padding:14px;background:#0c1727;border-radius:10px}</style></head><body><div class="box"><h1>Free Fire Order Tracking</h1><input id="oid" placeholder="Order ID"><input id="uid" placeholder="Free Fire UID"><button id="go">Check Status</button><div class="result" id="result" hidden></div></div><script>document.getElementById('go').onclick=async()=>{let r=document.getElementById('result');r.hidden=false;r.textContent='Checking…';try{let u=new URL('api/orders.php',location.href);u.searchParams.set('action','track');u.searchParams.set('order_id',document.getElementById('oid').value);u.searchParams.set('uid',document.getElementById('uid').value);let x=await fetch(u),d=await x.json();if(!x.ok||!d.ok)throw Error(d.message);r.innerHTML='<b>Status:</b> '+d.status+'<br><b>Product:</b> '+d.product_name+'<br><b>Amount:</b> Rs '+Number(d.amount).toFixed(2)}catch(e){r.textContent=e.message}}</script></div></body></html>